// components/poll/Poll.jsx
import { useDispatch, useSelector } from "react-redux";
import { votePoll } from "../../redux/actions/tweetActions";

export default function Poll({ tweet }) {
  const dispatch = useDispatch();
  const currentUserId = useSelector(s => s.currentProfile.data?._id);

  if (!tweet.poll) return null;

  const total = tweet.poll.options.reduce((s, o) => s + (o.votes || 0), 0);
  const expired = new Date(tweet.poll.expiresAt) < new Date();
  const alreadyVoted = tweet.poll.voters?.some?.(v => v === currentUserId);

  const handleVote = (idx) => {
    if (expired || alreadyVoted) return;
    dispatch(votePoll({ tweetId: tweet._id, optionIndex: idx }));
    // Your reducers can set a "modifiedTweet" flag, which already causes re-fetch in Tweet view.
  };

  return (
    <div className="poll">
      <div className="poll__q">{tweet.poll.question}</div>
      <div className="poll__opts">
        {tweet.poll.options.map((opt, idx) => {
          const pct = total ? Math.round((opt.votes / total) * 100) : 0;
          return (
            <button
              key={idx}
              className="poll__btn"
              disabled={expired || alreadyVoted}
              onClick={() => handleVote(idx)}
            >
              {opt.text}
              {(expired || alreadyVoted) && ` • ${pct}% (${opt.votes || 0})`}
            </button>
          );
        })}
      </div>
      <div className="poll__meta">
        {expired ? "Poll ended" : "Poll active"} • {total} votes
      </div>
    </div>
  );
}
